div.script:
(function () {
	'use strict';
	if (!window.SNC)
		window.SNC = {NotifyUi:{}};
	if (!SNC.NotifyUi)
		SNC.NotifyUi = {};
	window.SNC.NotifyUi.MSG = {
		"Initializing...": "${JS_STRING:gs.getMessage('Initializing...')}",
		"Mute": "${JS_STRING:gs.getMessage('Mute')}",
		"Unmute": "${JS_STRING:gs.getMessage('Unmute')}",
		"Back online": "${JS_STRING:gs.getMessage('Back online')}",
		"Disconnected from network": "${JS_STRING:gs.getMessage('Disconnected from network')}",
		"Call connecting...": "${JS_STRING:gs.getMessage('Call connecting...')}",
		"Call in progress": "${JS_STRING:gs.getMessage('Call in progress')}",
		"Calling...": "${JS_STRING:gs.getMessage('Calling...')}",
		"Call ended": "${JS_STRING:gs.getMessage('Call ended')}",
		"Incoming call from...": "${JS_STRING:gs.getMessage('Incoming call from...')}",
		"Call cancelled": "${JS_STRING:gs.getMessage('Call cancelled')}",
		"Someone": "${JS_STRING:gs.getMessage('Someone')}",
		"Access to microphone is denied": "${JS_STRING:gs.getMessage('Access to microphone is denied')}",
		"Close": "${JS_STRING:gs.getMessage('Close')}"
	};
	if (!window.GlideAjax) {
		window.nowapi = {};
		var script = document.createElement('script');
		script.setAttribute('src', '/scripts/classes/nowapi/GlideAjax.js');
		script.addEventListener('load', function() {
			SNC.Notify._defineNow();
		});
		document.head.appendChild(script);
	}
}());
